      vertexShader: 'attribute float size; attribute float sel; uniform float uPR; varying float vS; void main(){ vS=sel; vec4 mv=modelViewMatrix*vec4(position,1.0); gl_PointSize=size*uPR*(300.0/-mv.z); gl_Position=projectionMatrix*mv; }',
      fragmentShader: 'varying float vS; void main(){ float d=length(gl_PointCoord-0.5); float core=smoothstep(0.16,0.0,d); float halo=smoothstep(0.5,0.0,d)*0.35; vec3 c=mix(vec3(0.95,0.86,0.62), vec3(1.0,0.55,0.35), vS); gl_FragColor=vec4(c, core+halo); }'
